  "srv.panel_dns_more": "Why and how to set it up",
  "srv.panel_dns_cascade": "For a cascade. Sites that go direct by an address list (a country, networks) get addresses for the exit's country: they open slower and may even go through the exit. Add them to a domain rule “Direct” (a whole zone works, .com) and give it “Own DNS for these sites” — a local one, e.g. 9.9.9.9: Cloudflare and Google are often blocked in the server's country.",
  "cp.hint": "Ready rules for a cascade: when “Default” goes through an exit, a country's sites go direct — by its addresses and domains, with that country's own DNS. The buttons show while there are no rules.", "cp.apply_ru": "Apply for Russia", "cp.apply_cn": "Apply for China", "cp.apply_ir": "Apply for Iran", "cp.dns_note": "“DNS on the server” is turned on with the rules: the country's own DNS doesn't work without it.", "cp.dns_confirm": "“DNS on the server” is turned on with the rules — the country's own DNS doesn't work without it.\n\nClients who already have their config keep the old DNS in it. For DNS on the server to work for them, each has to scan the QR code or import the config file again. New clients get it right away.\n\nContinue?", "cp.dns_on": "DNS on the server is on", "cp.dns_failed": "The rules are saved, but DNS on the server didn't turn on: {e}", "cp.applied": "Rules for {country} applied", "srv.pdns_direct_fb": "Encrypted DNS doesn't answer directly from the server's country: for clients that go direct, names are looked up at the local DNS {dns} without encryption.", "srv.pdns_direct_down": "Encrypted DNS doesn't answer directly from the server's country: clients that go direct won't find sites. Enter local servers in the DNS field and choose “No encryption”, or give these clients an exit.",
  "srv.panel_dns_why": "Why. Sites give addresses close to whoever asked DNS. DNS on the server asks the same way the client's traffic goes, so sites through an exit open fast and the region matches. Queries are encrypted: the ISP can't see or spoof them.",
  "srv.panel_dns_best": "Setup. Encryption: DoH. In the DNS field: 1.1.1.1, 8.8.8.8. After turning it on, give clients new configs.",
  "srv.panel_dns_on": "Running on {addr}",
  "srv.panel_dns_stats": "{q} queries, {c} from cache",
  "srv.pdns_enc": "DNS query encryption",
  "srv.pdns_enc_doh": "DoH — HTTPS, port 443 (recommended)",
  "srv.pdns_enc_dot": "DoT — TLS, port 853",
  "srv.pdns_enc_plain": "No encryption",
  "srv.pdns_enc_hint": "For DNS on the server. The servers in the DNS field must support encryption: 1.1.1.1, 1.0.0.1, 8.8.8.8, 8.8.4.4, 9.9.9.9, 149.112.112.112 do. If the encrypted channel is unavailable, plain DNS is not used — except on the “direct” path of a server in Russia, China or Iran: there names are asked at the local DNS.",
