  "srv.panel_dns_more": "چرا و چطور تنظیم کنیم",
  "srv.panel_dns_cascade": "برای آبشار. سایت‌هایی که با فهرست نشانی‌ها (کشور، شبکه‌ها) مستقیم می‌روند، نشانی‌های کشور خروجی را می‌گیرند: کندتر باز می‌شوند و حتی ممکن است از خروجی بروند. آن‌ها را به قانون دامنهٔ «مستقیم» بیفزایید (یک ناحیهٔ کامل هم می‌شود، ‎.ir‎) و «DNS ویژهٔ این سایت‌ها» را برایش بگذارید — یک DNS محلی، مثلاً 178.22.122.100: Cloudflare و Google در کشور سرور اغلب مسدودند.",
