  "srv.panel_dns_why": "چرا. سایت‌ها نشانی نزدیک به پرسندهٔ DNS می‌دهند. DNS روی سرور از همان راهی می‌پرسد که ترافیک کلاینت می‌رود، پس سایت‌هایی که از خروجی می‌روند سریع باز می‌شوند و منطقه یکی است. پرسش‌ها رمزگذاری می‌شوند: ارائه‌دهنده آن‌ها را نمی‌بیند و جعل نمی‌کند.",
